<template>
  <div class="flex container h-full w-full">
    <SideNav />
    
    <div class="flex-1 flex flex-col h-full">
      <div class="px-4 py-3 border-b border-lighter flex items-center">
        <router-link :to="{ name: 'Chats' }" class="mr-4">
          <i class="fas fa-arrow-left text-xl text-blue"></i>
        </router-link>
        
        <div v-if="chat && otherUser" class="flex items-center">
          <div class="grid flex-none mr-3">
            <img :src="otherUser.avatar || '/default_profile.png'"
                 class="col-start-1 row-start-1 block w-10 h-10 rounded-full" />
            <UserStatusDot :user="otherUser" />
          </div>
          <div>
            <p class="font-bold">{{ otherUser.username }}</p>
            <p class="text-sm text-dark">@{{ chat.other_user_id }}</p>
          </div>
        </div>
      </div>

      <!-- Messages -->
      <div class="flex-1 overflow-y-auto p-4" ref="messageContainer">
        <div v-if="loading" class="flex justify-center">
          <Loader :loading="loading" />
        </div>

        <template v-else>
          <div v-for="message in messages" :key="message.id" 
               class="mb-4 flex"
               :class="{'justify-end': message.sender_id === currentUserId}">
            <div class="max-w-[75%] break-words rounded-lg px-4 py-2"
                 :class="message.sender_id === currentUserId ?
                        'bg-blue text-white' : 'bg-lighter'">
              <p v-linkify>{{ message.text }}</p>
              <p class="text-xs mt-1 text-gray-500">
                {{ $filters.timeago(message.created_at) }}
              </p>
            </div>
          </div>
        </template>
      </div>

      <!-- Message Input -->
      <div class="border-t border-lighter px-4 py-3">
        <form @submit.prevent="sendMessage" class="flex items-center">
          <div class="relative mr-2" data-emoji-anchor>
            <button
                type="button"
                @click="showEmojiPicker = !showEmojiPicker"
                class="rounded-full w-9 h-9 flex items-center justify-center hover:bg-lightblue"
                aria-label="Add emoji"
                title="Add emoji"
                :aria-expanded="showEmojiPicker"
            >
              <i class="far fa-smile text-blue text-lg" aria-hidden="true"></i>
            </button>
            <EmojiPicker
                v-if="showEmojiPicker"
                drop-up
                @select="insertEmoji"
                @close="showEmojiPicker = false"
            />
          </div>
          <input ref="messageInput"
                 v-model="newMessage"
                 type="text"
                 placeholder="Type a message..."
                 class="flex-1 rounded-full border border-lighter px-4 py-2 mr-2" />
          <button type="submit" 
                  class="bg-blue text-white rounded-full px-6 py-2">
            Send
          </button>
        </form>
      </div>
    </div>
  </div>
</template>

<script>
import {defineAsyncComponent} from "vue";
import {warpnetService} from "@/service/service";
import {toast} from "@/lib/toast";
import {clampRunes, focusCaret, insertEmoji} from "@/lib/emoji";
import UserStatusDot from "@/components/UserStatusDot.vue";

// Mirrors messageLimit in core/handler/chat.go.
const messageCharLimit = 5000;

export default {
  name: 'Chat',
  components: {
    SideNav: defineAsyncComponent(() => import('../components/SideNav.vue')),
    Loader: defineAsyncComponent(() => import('../components/Loader.vue')),
    EmojiPicker: defineAsyncComponent(() => import('@/components/EmojiPicker.vue')),
    UserStatusDot,
  },
  data() {
    return {
      loading: true,
      chat: null,
      messages: [],
      newMessage: '',
      chatId: undefined,
      currentUserId: undefined,
      otherUser: undefined,
      refreshTimer: null,
      refreshInFlight: false,
      showEmojiPicker: false,
    };
  },
  watch: {
    // Runes, not UTF-16 units: matches the limit the node enforces.
    newMessage(value) {
      const clamped = clampRunes(value, messageCharLimit);
      if (clamped !== value) this.newMessage = clamped;
    },
  },
  methods: {
    insertEmoji(emoji) {
      const field = this.$refs.messageInput;
      const next = insertEmoji({
        text: this.newMessage,
        emoji,
        field,
        limit: messageCharLimit,
      });
      if (!next) return;
      this.newMessage = next.text;
      this.$nextTick(() => focusCaret(field, next.caret));
    },
    async loadChat() {
      try {
        this.chat = await warpnetService.getChat(this.chatId);
      } catch (error) {
        console.error('Error loading chat:', error);
      }
    },

    async loadMessages() {
      try {
        const messages = await warpnetService.getDirectMessages(
            {chatId:this.chatId, cursorReset:true},
        );

        this.messages = [...messages, ...this.messages];
      } catch (error) {
        console.error('Error loading messages:', error);
      }
    },

    // The peer's name and avatar fill in whenever they arrive; the
    // messages must not wait behind their node.
    async loadOtherUser() {
      if (!this.chat) return;
      try {
        const otherId = this.chat.owner_id !== this.currentUserId
            ? this.chat.owner_id
            : this.chat.other_user_id;
        const u = await warpnetService.getProfile(otherId);
        if (!u || !u.id) return;
        this.otherUser = u;
        try {
          const avatar = await warpnetService.getImage({userId: u.id, key: u.avatar_key});
          if (avatar) this.otherUser = {...u, avatar};
        } catch (err) {
          console.warn('failed to load chat avatar:', err);
        }
      } catch (err) {
        console.error('failed to load chat user:', err);
      }
    },

    async sendMessage() {
      if (!this.newMessage.trim()) return;

      const text = this.newMessage;
      try {
        await warpnetService.sendDirectMessage({
          chatId: this.chatId,
          receiverId: this.otherUser.id,
          text,
        });
        // Don't push the raw send result (it can be empty and render a blank
        // bubble); clear the input and let the poll surface the stored message.
        this.newMessage = '';
        this.scrollToBottom();
      } catch (error) {
        console.error('Error sending message:', error);
        toast.error(error?.message || "Couldn't send the message. Please try again.");
      }
    },

    scrollToBottom() {
      this.$nextTick(() => {
        const container = this.$refs.messageContainer;
        container.scrollTop = container.scrollHeight;
      });
    },

    // Poll-driven live updates (no server push on the bridge): re-fetch
    // page 1 and merge new messages in by id so incoming messages appear
    // without a manual page reload.
    async refreshMessages() {
      if (this.refreshInFlight || this.loading) return;
      this.refreshInFlight = true;
      try {
        const page = await warpnetService.getDirectMessages(
            {chatId: this.chatId, cursorReset: true},
        );
        const known = new Set(this.messages.map((m) => m && m.id));
        const fresh = page.filter((m) => m && m.id && !known.has(m.id));
        if (fresh.length > 0) {
          this.messages = [...this.messages, ...fresh]
              .sort((a, b) => new Date(a.created_at) - new Date(b.created_at));
          this.scrollToBottom();
          warpnetService.markChatRead(this.chatId);
        }
      } catch (err) {
        console.error('Failed to refresh messages:', err);
      } finally {
        this.refreshInFlight = false;
      }
    },
  },
  async created() {
    console.log("loading component:", this.$options.name);
    this.currentUserId = this.$route.params.id;
    this.chatId = this.$route.params.chatId;

    await Promise.all([
      this.loadChat(),
      this.loadMessages()
    ]);
    this.loading = false;
    this.scrollToBottom();
    warpnetService.markChatRead(this.chatId);

    this.loadOtherUser();

    this.refreshTimer = setInterval(() => this.refreshMessages(), 3000);
  },
  beforeUnmount() {
    if (this.refreshTimer) {
      clearInterval(this.refreshTimer);
      this.refreshTimer = null;
    }
    // Everything on screen was seen, including own just-sent messages
    // that bumped the chat's updated_at.
    warpnetService.markChatRead(this.chatId);
  },
};
</script>